const files = $('Load Skills').all(), texts = $('Files to Text').all();
const inp = $('Source to Process').first().json, src = $('Load Source').first().json;
const context = $('Project Context').all().map(i => i.json).filter(x => x.id);
const domain = String(inp.domain || '');
const DOMAINS = {"All domains": "", "Healthcare": "healthcare", "Public service": "public_service", "Agriculture": "agriculture", "Education": "education"};
const label = Object.keys(DOMAINS).find(k => DOMAINS[k] === domain) || domain;
let searchSkill = '', module = '';
const defs = {};   // one-paragraph definition of every domain, for the domain tags
texts.forEach((t, i) => {
  const { fileName: name, directory: dir = '' } = files[i].binary.data;
  if (dir.endsWith('/search') && name === 'SKILL.md') searchSkill = t.json.data;
  else if (dir.endsWith('/domains') && /^[a-z_]+\.md$/.test(name)) {
    const key = name.replace(/\.md$/, ''), m = String(t.json.data).match(/\*\*AI4SG in [^*]+\*\*:?([\s\S]*?)\n\s*\n/);
    if (m) defs[key] = m[1].replace(/\s+/g, ' ').trim();
    if (domain && key === domain) module = t.json.data;
  }
});
const tagKeys = Object.keys(defs).sort();
const ctx = context.length ? `\n\n## Other sources about the same project\nThe search agent says this source is about "${src.project_guess}". ` +
  `Already screened or analysed, under that name:\n` + context.map(c => `- ${c.kind === 'project' ? 'Known project ' : 'Source: '}${c.headline}${c.reason ? ' (' + c.reason + ')' : ''}`).join('\n') +
  `\nA news story or report about a project whose AI is established by such sources does not have to describe the AI itself. If this source ` +
  `is about the same project (check the name, organisation and place), judge is_ai4sg for the project as a whole and say so in reason; judge ` +
  `relevance by what this source adds about the project's deployment, use or results.` : '';
// the text comes from the library (Project Context sits in between, so it is read by name, not from the input)
const doc = String($('Read from Library').first().json.text || '').replace(/\s+/g, ' ').trim();
const head = `URL: ${src.url}\nTitle: ${src.title || ''}\nCountry: ${src.country}\nLanguage: ${src.language}` +
  (src.project_guess ? `\nProject named by the search agent: ${src.project_guess}` : '') + (module ? `\nDomain of this run: ${label}` : '');
return [{ json: { min_relevance: Number(inp.min_relevance) || 0.6, chars: doc.length, prompt:
  `${searchSkill}${module ? `\n\n---\n\n# Domain module for this run: ${label}\n\n${module}` : ''}\n\n## Screening task\n` +
  `You are screening ONE source before the experts' detailed review. Using the definition in "What counts as AI for Social Good" above, ` +
  `decide whether this source describes a concrete AI system, project, evaluation or policy whose primary purpose is a social benefit in the ` +
  `stated country. Generic AI news, AI policy talk without a concrete project, commercial products, digitisation without a learned model, and ` +
  `pages that merely mention AI do not qualify. A forecast, early-warning or decision-support system is AI only when it uses a learned ` +
  `model (machine learning, deep learning, a language model, computer vision ...): a mechanistic or process-based model (e.g. a weather-driven ` +
  `crop-disease model), a statistical index, fixed thresholds or fixed rules are not AI, so is_ai4sg is false for them even when the source ` +
  `calls them "predictive" or "smart". When the source says AI is used but not which method, the system can still count.\n` +
  (module ? `This run covers the ${label} domain only. Set in_domain to true only if the source belongs to this domain AND meets the domain ` +
            `module's "What counts in this domain" (including its requirement of real testing, deployment or use); otherwise false.\n`
          : `Set in_domain to true (no domain was chosen for this run).\n`) +
  `Return: is_ai4sg (boolean), in_domain (boolean), relevance (0-1: how clearly and centrally the source is about such a project), ` +
  `reason (one English sentence; if in_domain is false, say why), headline_en (one English sentence: who does what, max 20 words), ` +
  `project_name (the short name of the AI project or tool, as a whole project: the same tool deployed in several places is one project; "" if none), ` +
  `implementing_org (who runs it, "" if not stated), ` +
  `evidence_type (the strongest evidence THIS source itself reports about the AI system's real use or effects: "rct" = randomised trial; ` +
  `"quasi_experimental" = comparison with a control group without randomisation; "observational" = analysis of real usage data, programme records, ` +
  `or an accuracy or implementation study in real use; "pilot_report" = a report of a pilot or deployment with some figures; "anecdotal" = ` +
  `announcements, descriptions or stories without data; "none" = nothing about real use), ` +
  `card (what a selector needs to choose, without reading the source, the few sources most worth an in-depth analysis: ` +
  `title_en; authors (up to 4 names, "" if none); organisation (the institution, agency or outlet behind the source); published (year or date); ` +
  `source_kind (e.g. journal article, working paper, trial registration, government report, programme or developer report, government web page, ` +
  `news article, blog); deployment (the intervention: "tool — place or phase"); ai_method (the AI or machine-learning method the source itself ` +
  `names, e.g. "CNN leaf-disease classifier", "LLM chatbot (GPT-4) with retrieval", "random-forest yield prediction"; "not stated" when the ` +
  `source only says AI or smart without naming a learned model; "none: <what it is>" for a mechanistic or statistical model, thresholds or ` +
  `fixed rules); primary_source (true when the source reports its own study, ` +
  `programme data or official figures; false when it repeats others' work, as most news does); key_figures (up to 5 short strings with the most ` +
  `important numbers it reports from real use: adoption, usage, reach, accuracy in real use, outcomes, costs; [] if none); summary (2 to 3 ` +
  `sentences: who did what with which AI, where, for whom, and what the source shows)), ` +
  `domains (every domain the source belongs to, from this list; several if it sits between domains, e.g. an AI advisory chatbot of a public ` +
  `farmer-subsidy scheme is both public_service and agriculture; [] if none:\n${tagKeys.map(k => `  - ${k}: ${defs[k]}`).join('\n')}).` +
  `${ctx}\n\n## Source\n${head}\n\n${doc.slice(0, 15000) || '(the text could not be read)'}`, domain, tag_keys: tagKeys } }];

// A source passes when it is AI4SG, relevant enough, and belongs to the run's domain or to another domain (it then waits in that
// domain's queue: a TB-screening paper found by a public-service run is tagged healthcare). If the model's answer still did not fit
// the format after the retries, nothing is decided: the source stays downloaded and is screened again in the next run.
const c = $('Compose Screen').first().json, o = $json.output;
if (!o) return [{ json: { ok: false, screen: { error: String($json.error?.message || $json.error || 'screen failed') } } }];
// tags = what the source actually is: every domain it belongs to (the run's domain is one of them only if it fits)
let tags = (Array.isArray(o.domains) ? o.domains : []).map(d => String(d).trim().toLowerCase().replace(/[\s-]+/g, '_')).filter(d => c.tag_keys.includes(d));
if (c.domain && o.in_domain === true) tags.unshift(c.domain);
tags = [...new Set(tags)];
const belongs = c.domain ? (o.in_domain === true || tags.some(d => d !== c.domain)) : true;
return [{ json: { ok: true, screen: o, tags, passed: o.is_ai4sg === true && belongs && (Number(o.relevance) || 0) >= c.min_relevance } }];
